def compute_order_amount(on_hand_inventory, pipeline_orders):
    base_stock = 447.97186701416774  # OPT_PARAM: {"initial": 447.97186701416774, "min": 300, "max": 700, "type": "float"}
    order_cap = 56.220359787271775  # OPT_PARAM: {"initial": 56.220359787271775, "min": 50, "max": 150, "type": "float"}
    safety_stock = 38.0718670141673  # OPT_PARAM: {"initial": 38.0718670141673, "min": 20, "max": 100, "type": "float"}
    demand_buffer = 117.9719018575716  # OPT_PARAM: {"initial": 117.9719018575716, "min": 80, "max": 200, "type": "float"}
    pipeline_weight = 0.6339884815323699  # OPT_PARAM: {"initial": 0.6339884815323699, "min": 0.3, "max": 1.0, "type": "float"}

    # Calculate inventory position
    inventory_position = on_hand_inventory + sum(pipeline_orders)

    # Calculate target inventory level with safety stock
    target_inventory = base_stock + safety_stock

    # Calculate base order quantity
    order_qty = target_inventory - inventory_position

    # Add demand buffer based on weighted pipeline orders
    if len(pipeline_orders) >= 3:
        recent_orders = sum(pipeline_orders[-3:])
        if recent_orders > demand_buffer:
            order_qty += demand_buffer * pipeline_weight

    # Apply order cap and ensure non-negative
    order_amount = max(0, min(order_qty, order_cap))

    return order_amount
